// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    // fuzzed params: a random uint256 used to derive a guess hash and a caller key
    function testFuzz_property(uint256 seed, uint256 attackerKey) public {
        // keep wide but avoid trivial zero-key for vm.addr (it's still valid though)
        vm.assume(attackerKey != type(uint256).max);

        address attacker = vm.addr(uint256(keccak256(abi.encodePacked(attackerKey))));
        // fund attacker so they can lock in guess with 1 ether
        vm.deal(attacker, 3 ether);

        // construct a guess hash from seed (fuzzed)
        bytes32 guess = keccak256(abi.encodePacked(seed));

        // attacker locks in guess for next block
        vm.startPrank(attacker);
        c.lockInGuess{value: 1 ether}(guess);
        vm.stopPrank();

        // advance one block so the stored block < current block and settle is callable
        vm.roll(block.number + 2);

        // We'll have attacker call settle twice in a row. On the correct contract,
        // the first settle clears guesses[attacker].block to 0, so the second
        // settle must revert (require(guesses[msg.sender].block != 0)).
        // On the mutant (which omits clearing), the second settle may NOT revert.

        bool firstOk;
        vm.startPrank(attacker);
        try c.settle() {
            firstOk = true;
        } catch {
            firstOk = false;
        }
        bool secondOk;
        try c.settle() {
            secondOk = true;
        } catch {
            secondOk = false;
        }
        vm.stopPrank();

        // General rule: For ALL admissible inputs, on the reference contract,
        // whenever the first settle() call succeeds (firstOk == true), the
        // contract cleared the stored guess.block and the immediate second
        // settle() MUST revert (secondOk == false). The mutant that omits
        // clearing can make secondOk == true for some inputs.
        assertTrue(!(firstOk && secondOk) );
    }
}
